const apply = () => { document.querySelectorAll('.save[aria-label]').forEach((b) => { b.removeAttribute('aria-label'); b.textContent = ''; b.style.backgroundImage = 'radial-gradient(circle, #e11d48 30%, transparent 32%)'; }); };
const mo = new MutationObserver(() => { mo.disconnect(); apply(); mo.observe(document.body, { childList: true, subtree: true }); });
apply();
